programs.haiku:
"""Planning-language detector for layers.15.mlp.down_proj component 9.

What it responds to: words that set up a plan, a method or a next step in
reasoning-style text. The strongest case is "me" or "'s" right after "Let"
("Let me try ...", "Let's see ..."), then hedges such as "maybe", "perhaps" and
"alternatively". Weaker positive values sit on "to" after a planning lead
("need to", "try to", "way to"), on planning verbs ("try", "use", "consider",
"check"), on pronouns that open a plan ("I", "we", "you") and on procedure words
("first", "then", "step", "approach"). The value also stays raised for a few tokens
after a planning cue, so the component is high through a whole planning phrase.
Descriptive and factual text (code, definitions, results) sits near zero.

The program reads only the current token, the one before it, and a short decaying
memory of recent cues, all within the same document.
"""

import math
from collections.abc import Mapping

READS: tuple[str, ...] = ()

CUES = {"Let", "let", "maybe", "perhaps", "alternatively", "try", "need", "consider", "using"}
LET_FOLLOWERS = {"me", "'s", "’s"}
HEDGES = {"maybe", "perhaps", "alternatively"}
PLAN_LEADS = {"need", "try", "want", "way", "better", "possible", "going", "trying", "tried", "how"}
PLAN_VERBS = {
    "try", "use", "using", "consider", "check", "need", "can", "calculate", "compute",
    "write", "see", "run", "think", "find", "define", "plot", "test", "verify", "start",
    "assume", "look", "apply", "solve", "implement",
}
PRONOUNS = {"I", "we", "We", "you"}
PROCEDURE = {"first", "then", "now", "step", "approach", "analysis", "further", "also", "must", "might"}
DECAY = math.exp(-1.0 / 3.0)


def step(carry, prefix, upstream: Mapping):
    words = [s.strip() for s in prefix.token_strings]
    cur = words[-1]
    same_doc = len(words) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]
    prev = words[-2] if same_doc else ""
    memory = carry if (carry is not None and same_doc) else 0.0

    if prev in ("Let", "let") and cur in LET_FOLLOWERS:
        value = 7.0
    elif cur.lower() in HEDGES:
        value = 3.3
    elif cur == "to" and prev in PLAN_LEADS:
        value = 0.8
    elif cur in PLAN_VERBS:
        value = 0.6
    elif cur in PRONOUNS or cur in PROCEDURE:
        value = 0.4
    else:
        value = 0.0
    value += 1.0 * memory

    # the memory now includes this token, for the next position
    new_memory = memory * DECAY + (1.0 if cur in CUES else 0.0)
    return new_memory, value

"""Source-marking "from" detector (negative).

The component is strongly negative on the preposition "from" when it says where something
comes from: a letter from, data from, students from, taken from, coming from. That is the
usual case after a noun or verb. It is weaker after an adjective or adverb, and near zero
when "from" marks distance, separation or difference (far from, apart from, range from,
different from, departing from). It is weakly negative on "by", on the foreign words for
"from" (aus, из, fra, vom), and on the token right after "from".

step() predicts those levels and 0 everywhere else. It reads only the current token and
the one before it.
"""

import wordnet

READS = ()

FROM = {" from", " From", "from", "From"}
FOREIGN_FROM = {" aus", " из", " от", " vom", " fra"}
BY = {" by", " By"}
SEPARATION = {
    "away", "apart", "aside", "far", "distance", "range", "ranges", "ranging", "ranged",
    "different", "differ", "differs", "difference", "distinct", "distinguished", "separate",
    "separated", "depart", "departs", "departing", "departure", "remote", "across",
}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if tok in FROM:
        if prev in SEPARATION:
            return carry, 0.0
        tags = wordnet.parts_of_speech(prev) if prev.isalpha() else set()
        return carry, -7.0 if tags & {"noun", "verb"} else -4.5
    if tok in FOREIGN_FROM:
        return carry, -4.0
    if tok in BY:
        return carry, -1.7
    if prev == "from":
        return carry, -3.5 if tok == " the" else -1.0
    return carry, 0.0

"""Layer 15, MLP hidden unit 13, read through the component (its activation is that unit's
value times 1.27, the component's only sizeable input direction).

The unit is open in code and closed in English prose, and its sign follows the syntax:
it is positive on C-style type keywords (`double`, `float`, `int`, `char`, `long`, `void`),
on array and pointer syntax (`[`, `[]`, `&`, `*`), and negative on closing brackets and on
library or wrapper type names (`Option`, `Some`, `None`, `List`, `Vec`, `Integer`,
`Request`, ...). Everything else predicts 0.

The weights are rounded class means measured on about 2M tokens of the training corpus. The
program is only a token-class readout: most of the variance comes from context it doesn't
see (the rest of the unit's input), so it explains only about 1% of the variance.
"""

READS = ()

FLOAT_TYPES = {"double", "float"}
C_TYPES = {"int", "long", "char", "short", "byte", "uint", "boolean", "bool", "void", "unsigned", "struct"}
POINTER_SYNTAX = {"&", "*", "&mut", "mut", "(&", "(*", ">&"}
CLOSING = {");", "();", "});", "];", '")', ")\\", '"));'}
LIBRARY_TYPES = {"Option", "Some", "None", "Optional", "List", "Vec", "Array", "Result", "Integer",
                 "Observable", "Intent", "Request", "Response"}


def value_of(token):
    if token in FLOAT_TYPES:
        return 3.0
    if token in C_TYPES:
        return 1.5
    if "[" in token or token in POINTER_SYNTAX:
        return 0.7
    if token in CLOSING:
        return -0.45
    if token in LIBRARY_TYPES:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(value_of(prefix.token_strings[-1].strip()))

"""Layer 15 MLP down_proj, component 14: a 'complement is coming' detector for research prose.

The component is mostly quiet (typical |activation| < 0.5) but fires strongly on the word that
opens a complement in scientific writing:
  - a clause word ("that", "whether", "how", "if", "between") right after a verb of finding,
    showing or investigating ("suggest that", "found that", "investigated whether", "association
    between"), or after a relational noun ("the link between", "evidence that"): strongest;
  - a relational noun itself ("effect", "impact", "role", "influence", "relationship", ...),
    especially after "the" or inside a research sentence;
  - "of" right after a relational noun ("the effect of", "the role of");
  - "does"/"can" right after "how"/"why"/"what" in a question.
Weaker bumps: a clause word elsewhere in research prose, and a comma after "However,"/"In addition,".
Everything else is predicted as 0, the component's typical small value.
"""

READS = ()

# Nouns that take a complement describing a relation or a result.
RELATION = {"effect", "effects", "influence", "impact", "impacts", "role", "relationship",
            "association", "correlation", "link", "interaction", "contribution", "implications",
            "linking", "connection", "difference", "relation"}
# Verbs of finding, showing, examining and hypothesising, which take a clause.
STUDY = {"investigate", "investigated", "examine", "examined", "determine", "determined", "study",
         "studied", "assess", "test", "tested", "evaluate", "analyze", "analyzed", "suggest",
         "suggests", "suggested", "show", "shown", "shows", "showed", "found", "find", "confirm",
         "indicate", "indicated", "ensure", "hypothesis", "aim", "objective", "explore", "consider",
         "whether"}
CLAUSE = {"that", "whether", "how", "if", "why", "which", "between"}
CONNECTIVE = {"however", "addition", "furthermore", "moreover", "therefore", "thus"}
DETERMINER = {"the", "this", "these", "its", "their", "a", "an"}


def step(carry, prefix, upstream):
    toks = [s.strip().lower() for s in prefix.token_strings[-9:]]
    word = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    research = any(t in STUDY or t in RELATION for t in toks[:-1])
    if word in CLAUSE:
        if prev in STUDY or prev in RELATION:
            return carry, 4.7
        return carry, 1.2 if research else 0.6
    if word in RELATION:
        return carry, 2.6 if (prev in DETERMINER or research) else 0.8
    if word == "of" and prev in RELATION:
        return carry, 4.1
    if word in ("does", "do", "did", "can") and prev in ("how", "why", "what"):
        return carry, 5.6
    if word == "," and prev in CONNECTIVE:
        return carry, 1.1
    return carry, 0.0

"""Upper ends of numeric ranges: "1972 to 1989", "3-7", "between 2 and 5".

The component reads the MLP's hidden state, and its activation is large on the
digits of the second number of a range, the upper end. Plain prose ranges
drive it most; dates, IDs, versions and math or code ("x=2-3") barely do.

Rules, read left to right with a short memory of the last number:
- A number that directly follows a range word ("to", "until", "through", or
  "and" within 8 tokens of "between") or a dash, and that follows an earlier
  number, is a range end. Its digits are scored one at a time:
    * the start of the range was itself after a dash (a date part like
      "2023-09-1"), or was after a math or code symbol ("=", "/", "+", "#"...),
      or the digits so far are below the start's digits: 1.0 (low);
    * digits so far equal the start's: 3.5 on the first digit, 8 after it;
    * digits so far above the start's: 7 on the first digit, 15 after it;
    * the end is longer than the start: 3.7.
- Other digits: 0.4. A range word or dash right after a number: 6 for a word,
  3.5 for a dash. Everything else: 0.
"""

READS = ()

DIGITS = "0123456789"
RANGE_WORDS = {"to", "until", "through"}
DASHES = {"-", "–", "—", "−"}
MATH_BEFORE = {"=", "/", "+", "@@", "#", "^", "}", "→", "-", "*", "²", "³", "_"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "last": "", "last_digit": False, "num": "", "sep": "",
                 "num_before": "", "low": "", "low_sep": "", "low_before": "", "btw": 0}
    st = carry
    st["btw"] = max(0, st["btw"] - 1)
    if s == "between":
        st["btw"] = 8
    value = 0.0
    if s == "":
        # a space ends the current number but keeps the last word for the range test
        if st["num"]:
            st["low"], st["low_sep"], st["low_before"], st["num"] = st["num"], st["sep"], st["num_before"], ""
        return st, 0.0
    if len(s) == 1 and s in DIGITS:
        if not st["num"]:
            # a new number: note which connector, if any, came just before it
            st["sep"] = "word" if st["last"] in RANGE_WORDS else ("dash" if st["last"] in DASHES else "")
            st["num_before"] = st["last"]
        st["num"] += s
        value = 0.4
        if st["sep"] and st["low"]:
            k = len(st["num"]) - 1
            n = len(st["num"])
            cmp = 2  # the end is longer than the start
            if n <= len(st["low"]):
                cmp = (st["num"] > st["low"][:n]) - (st["num"] < st["low"][:n])
            if st["low_sep"] == "dash" or cmp < 0 or st["low_before"] in MATH_BEFORE:
                value = 1.0
            elif cmp == 0:
                value = 3.5 if k == 0 else 8.0
            elif cmp == 1:
                value = 7.0 if k == 0 else 15.0
            else:
                value = 3.7
        st["last_digit"] = True
    else:
        if st["num"]:
            st["low"], st["low_sep"], st["low_before"], st["num"] = st["num"], st["sep"], st["num_before"], ""
        if (s in RANGE_WORDS or s in DASHES or (s == "and" and st["btw"])) and st["last_digit"]:
            value = 6.0 if s in RANGE_WORDS else 3.5
        st["last_digit"] = False
    st["last"] = "to" if (s == "and" and st["btw"]) else s
    return st, value

"""Layer 15 MLP unit 24 (down_proj component 24): a small offset by the current token's type.

The component's activation is a dense linear read-out of the layer's MLP hidden state. Almost
none of it follows from the text's surface: a token's type explains under 1% of its variance.
What it does show is a small offset by type: whitespace and punctuation tokens sit a little
below zero, digits a little above, other tokens near zero. This program predicts those offsets.
"""

import unicodedata

READS = ()

OFFSET = {"whitespace": -0.055, "punct": -0.055, "digit": 0.032, "other": -0.003}


def token_type(text):
    body = text.strip()
    if body == "":
        return "whitespace"
    if all(unicodedata.category(c)[0] in "PS" for c in body):
        return "punct"
    if body.isdigit():
        return "digit"
    return "other"


def step(carry, prefix, upstream):
    return carry, OFFSET[token_type(prefix.token_strings[-1])]

"""Layer 15, MLP hidden unit 28 (the down_proj component :28), read from the prose/maths split.

This component reads mostly one hidden unit of the layer-15 MLP: unit 28 carries about two
thirds of its input direction, so its activation tracks that unit's value. The activation is
about zero at the first token of each document, and otherwise varies from about -20 to +20
with no simple cause. Its sign
follows a rough split of the text it is reading:

- positive after clause connectives and timing words in English prose, where the next word is
  often a verb or "later" ("and then", "you can", "we'll", "will", "before", "later");
- negative inside digits and arithmetic or code symbols ("2", "^", "-", "=", "(").

This program writes those tendencies as constants. It sees only the current token and whether
it starts a document; it keeps no state beyond that. It explains very little of the variance:
most of the activation is not tied to any token or word class.
"""

import re

READS = ()

TIMING_WORDS = {" then", " Then", " later", " before", " after", " subsequently", " afterwards"}
CLAUSE_WORDS = {" and", " can", " will", " to", " be", " let", " always", " just", " simply", "'ll"}


def is_maths(text):
    """A digit, sign or operator with no letters: arithmetic or code, not prose."""
    return bool(re.search(r"[0-9²³+\-*/^=]", text)) and not re.search(r"[A-Za-z]", text)


def step(carry, prefix, upstream):
    starts_document = len(prefix.document_ids) == 1 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if starts_document:
        return carry, 0.0
    text = prefix.token_strings[-1]
    if text in TIMING_WORDS:
        return carry, 0.25
    if text in CLAUSE_WORDS:
        return carry, -0.02
    if is_maths(text):
        return carry, -0.08
    return carry, -0.04

"""Conversion-frame detector: component 38 of layers.15 mlp.down_proj (Qwen3-1.7B).

What it responds to: the model reading a conversion or change-of-state.
  * The verb "convert" (and forms) is strongly negative (about -6).
  * Other transform verbs (translate, transform, map, multiply, split, ...) are mildly
    negative (about -2).
  * The word straight after a convert verb, the object slot in "convert [a] ... from",
    is strongly negative (about -2 times the verb's strength).
  * "from" is negative (about -1.3) as a source word. It is much more negative (-6) within
    a few tokens of a convert verb, and -4 right after a motion or change word
    ("transition from", "move from", "change from"). After "different", "able", "without"
    and similar it is left at 0.
  * Chinese 将 and 把 ("take ... and turn into") are about -2.
Everything else is 0. This is a readable sketch: it explains the negative tail and
leaves out most of the variance, which is diffuse.
"""

READS = ()

STRONG = {"convert", "converts", "converting", "converted", "Convert", "Converts", "Converting"}
MEDIUM = {"translate", "translates", "transform", "transforms", "transforming", "transpose",
          "rewrite", "rename", "replace", "replaces", "replacing", "multiply", "divide",
          "parse", "split", "splits", "map", "mapping", "transfer", "transferring"}
MOTION = {"transition", "transferred", "move", "moved", "moving", "go", "going", "goes",
          "change", "changed", "changing", "increased", "down", "up", "flow", "shift"}
NOT_SOURCE = {"different", "differ", "differs", "able", "known", "excluded", "without", "import", "picked"}
FROM = {"from", "From", "从", "從"}
TAKE = {"将", "把"}
ARTICLES = {"a", "an", "the", "each", "every"}


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[-1].strip()
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[2]:
        last, strength, last_motion, prev = None, 0.0, None, ""
    else:
        last, strength, last_motion, prev = carry[0], carry[1], carry[3], carry[4]
    dist = None if last is None else t - last
    if word in STRONG:
        value, last, strength = -6.0, t, 6.0
    elif word in MEDIUM:
        value, last, strength = -2.0, t, 2.0
    elif word in FROM:
        if prev in NOT_SOURCE:
            value = 0.0
        elif dist is not None and dist <= 5 and strength >= 6:
            value = -6.0
        elif last_motion is not None and t - last_motion <= 2:
            value = -4.0
        else:
            value = -1.3
    elif word in TAKE:
        value = -1.9
    elif dist == 1 and word in ARTICLES:
        value = -2.0 * strength
    elif dist == 1:
        value = -strength / 2
    else:
        value = 0.0
    if word in MOTION:
        last_motion = t
    return (last, strength, doc, last_motion, word), value

"""Layer 15 MLP output, component 61: the opening of an `if` condition in code.

This component responds to the keyword that begins a conditional test in source code
(`if`, `elif`, `unless`) and to the first few tokens of that test, such as the `(` and
the operand in `if (x == 0)`. It is strongest on the keyword itself and fades by
about 30% per token. The test ends at its matching `)`, or at a `{`, `:` or newline.
The same word in ordinary prose ("if you are new...") gives only a weak response.
Everywhere else the program predicts 0.

It explains about a fifth of the variance. The rest is mostly on the token just
before a comparison operator (`==`, `>`, `!=`, `instanceof`) in code, which a
program reading only the prefix cannot anticipate.
"""

READS = ()

CONDITION_WORDS = {"if", "elif", "unless"}
CODE_CHARS = set("{};()=<>[]_\\/*&|!#$")
CODE_WINDOW = 24   # recent tokens used to judge whether we are reading code
CODE_SHARE = 0.2   # share of those tokens that look like code to count as code
CODE_LEVEL = 9.0   # response at the keyword in code
PROSE_LEVEL = 2.0  # response at the keyword in prose
FADE = 0.7         # response multiplier per token into the condition


def _looks_like_code(text):
    indented = text.startswith(("\t", "  ")) or "\n    " in text
    return indented or any(ch in CODE_CHARS for ch in text)


def step(carry, prefix, upstream):
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = {"start": None, "depth": 0, "code": 0.0}
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    t = len(prefix.token_strings) - 1
    if word in CONDITION_WORDS:
        recent = prefix.token_strings[max(0, t - CODE_WINDOW + 1): t + 1]
        share = sum(_looks_like_code(s) for s in recent) / len(recent)
        carry.update(start=t, depth=0, code=share)
    if carry["start"] is not None:
        if "\n" in text and t > carry["start"]:
            carry["start"] = None
        else:
            if word == "(":
                carry["depth"] += 1
            elif word == ")":
                carry["depth"] -= 1
            closes = word == ")" and carry["depth"] <= 0 and t > carry["start"] + 1
            if word in ("{", ":") or closes:
                carry["start"] = None
    if carry["start"] is None:
        return carry, 0.0
    level = CODE_LEVEL if carry["code"] > CODE_SHARE else PROSE_LEVEL
    return carry, level * FADE ** (t - carry["start"])
